import fs from 'node:fs/promises';import{gunzipSync}from'node:zlib';import{createHash}from'node:crypto';import{SegmentGrid,streetDistance,streetSegments}from'/ABSOLUTE_REPO_ROOT/src/canalRecall/streetFronts.ts';
const root=process.cwd();const sha=(b:any)=>createHash('sha256').update(b).digest('hex');
const A=[4.89949,52.37460],B=[4.898626,52.373866];const kx=111320*Math.cos(A[1]*Math.PI/180),ky=110540;const dx=(B[0]-A[0])*kx,dy=(B[1]-A[1])*ky,L=Math.hypot(dx,dy);const loc=(p:any)=>{const x=(p[0]-A[0])*kx,y=(p[1]-A[1])*ky;return {along:(x*dx+y*dy)/L,depth:(dx*y-dy*x)/L,x,y}};const sources:any[]=[];async function read(file:string,gz=false){const b=await fs.readFile(file);sources.push({file,sha256:sha(b)});return JSON.parse((gz?gunzipSync(b):b).toString())}
const routing=await read('public/data/extracts/amsterdam/streets-routing.json');const nativePath=routing.find((w:any)=>w.id==='routing_4398');const paths=routing.filter((w:any)=>w.highway).flatMap((w:any)=>(w.paths??[w.path]).map((p:any)=>({highway:w.highway,points:p.map((q:any)=>[q[1],q[0]])})));const road=new SegmentGrid(streetSegments([{highway:nativePath.highway,points:nativePath.path.map((p:any)=>[p[1],p[0]])}],{lng:A[0],lat:A[1]}));
const features=new Map(),facts=new Map();for(const tile of ['8413/5383','8413/5384','8414/5383','8414/5384']){const file='public/data/extracts/amsterdam/building-tiles/14/'+tile+'.geojson.gz';try{const d=await read(file,true),f=await read('public/data/extracts/amsterdam/building-facts/14/'+tile+'.json.gz',true);for(const [id,row]of Object.entries(f.buildings))facts.set(id,row);for(const feature of d.features){const polys=feature.geometry.type==='Polygon'?[feature.geometry.coordinates]:feature.geometry.coordinates;const pts=polys.flatMap((p:any)=>p[0]).map(loc);if(pts.some((p:any)=>p.along>-40&&p.along<L+40&&Math.abs(p.depth)<55))features.set(feature.properties.id,feature)}}catch(e){throw e}}
const walls:any[]=[],flat:number[]=[],owners:number[]=[];let owner=0;for(const[id,f]of features){const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;for(const poly of polys)for(let ri=0;ri<poly.length;ri++){const ring=poly[ri].map(loc);let area=0;for(let i=1;i<ring.length;i++)area+=ring[i-1].x*ring[i].y-ring[i].x*ring[i-1].y;const sign=(area>0?1:-1)*(ri? -1:1);for(let i=1;i<ring.length;i++){const a=ring[i-1],b=ring[i],wx=b.x-a.x,wy=b.y-a.y,len=Math.hypot(wx,wy);if(len<.1)continue;const w={id,owner,hole:ri>0,x0:a.x,y0:a.y,x1:b.x,y1:b.y,nx:sign*wy/len,ny:-sign*wx/len,len,start:poly[ri][i-1],end:poly[ri][i]};walls.push(w);flat.push(a.x,a.y,b.x,b.y);owners.push(owner)}}owner++}const obstacles=new SegmentGrid(flat,25,owners);const fronts=walls.filter(w=>{if(w.hole)return false;const a=loc(w.start),b=loc(w.end);const depth=(a.depth+b.depth)/2;return Math.max(a.along,b.along)>0&&Math.min(a.along,b.along)<L&&depth>0&&depth<20&&streetDistance(w,road,obstacles,w.owner,32)<Infinity});
const grouped:any[]=[];for(const[id,f]of features){const ws=fronts.filter(w=>w.id===id);if(!ws.length)continue;grouped.push({nativeId:id,heightM:f.properties.height,facts:facts.get(id.replace('NL.IMBAG.Pand.','P')),footprint:f.geometry,streetfrontWalls:ws.map(w=>({start:w.start,end:w.end,widthM:w.len,alongStartM:loc(w.start).along,alongEndM:loc(w.end).along,normal:[w.nx,w.ny],streetDistanceM:streetDistance(w,road,obstacles,w.owner,32)})),alongM:Math.min(...ws.flatMap(w=>[loc(w.start).along,loc(w.end).along]))})}grouped.sort((a,b)=>a.alongM-b.alongM);
await fs.writeFile('/tmp/map-recall-next-canal-inventory.json',JSON.stringify({segment:[A,B],side:1,lengthM:L,nativeRoutingPath:nativePath,sources,method:'Native polygon boundary rays: SegmentGrid and streetDistance use actual routing_4398, 25m grid, all neighboring native walls as blockers, 32m ray reach; retain street-facing exterior runs crossing along interval on east-bank side, depth under20m. Corners crossing endpoints retained.',inventory:grouped},null,2));console.log(JSON.stringify({lengthM:L,frontages:grouped.map(g=>({id:g.nativeId,along:Math.round(g.alongM),year:g.facts?.[0]}))}));
